#!/usr/bin/env python
"""Refresh the auto-generated results block in README.md from results/headline.json.

Only the text between the RESULTS:START / RESULTS:END markers is replaced.
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from ecoverse import config  # noqa: E402

START, END = "<!-- RESULTS:START -->", "<!-- RESULTS:END -->"


def block(hl):
    lines = [START, "", "_Auto-generated by `scripts/update_readme.py` from `results/headline.json` "
             "(do not edit by hand)._", ""]
    lines += ["| Metric | Value |", "|---|---|",
              f"| Land analysed | {hl['land_km2']:.1f} km² at 20 m |",
              f"| Irrigated greenery detected | {hl['irrigated_greenery_ha']:,.0f} ha |",
              f"| Land with ≥1 native survivor (no routine irrigation) | {hl['pct_land_with_native_survivor']:.1f} % |",
              f"| Mean irrigation saving vs. Conocarpus + lawn | {hl['mean_saving_mm']:.0f} mm/yr "
              f"(90 % MC interval {hl['saving_mm_ci90'][0]:.0f}–{hl['saving_mm_ci90'][1]:.0f}) |",
              f"| Median recommendation stability (Monte Carlo) | {hl['median_stability']:.2f} |",
              f"| Land keeping the same pick in ≥80 % of draws | {hl['pct_stable_80']:.1f} % |",
              f"| Probe sites planned | {hl['n_probe_sites']} |", ""]
    lines += ["**Water budget**", "", "| Scenario | Area (ha) | Baseline (m³/yr) | Ecoverse (m³/yr) | Saving |",
              "|---|---|---|---|---|"]
    for r in hl["water_budget"]:
        lines.append(f"| {r['scenario']} | {r['area_ha']:,.0f} | {r['baseline_m3_yr']:,.0f} | "
                     f"{r['ecoverse_m3_yr']:,.0f} | {r['saving_pct']:.0f} % |")
    lines += ["", "**Most-recommended native species (share of land)**", ""]
    lines += [f"{i}. {n} — {p:.1f} %" for i, (n, p) in enumerate(hl["top_species"], 1)]
    if hl.get("transfer_cv"):
        lines += ["", "**Hyperspectral → Sentinel-2 transfer (spatial-block CV)**", "",
                  "| Hyperspectral feature | Pixels | n | Linear R² | Boosted R² | Info only hyperspectral sees |",
                  "|---|---|---|---|---|---|"]
        for r in hl["transfer_cv"]:
            if "r2_boosted" in r and r["r2_boosted"] == r["r2_boosted"]:
                lines.append(f"| {r['target']} | {r.get('pixels','')} | {r['n']:,} | {r['r2_linear']:.2f} | {r['r2_boosted']:.2f} | "
                             f"{r['hyperspectral_only_info_pct']:.0f} % |")
        lines.append(f"\nGypsum signal transferred into the Bahrain salinity layer: **{hl['gypsum_transferred']}**")
    soil = config.RESULTS_DIR / "hyperspectral_soil_recovery.json"
    if soil.exists():
        s = json.loads(soil.read_text())
        lines.append(f"\nSentinel-2 recovers the {s['k']} hyperspectral soil classes with balanced accuracy "
                     f"**{s['soil_class_balanced_accuracy']:.2f}** (chance {s['chance']:.2f}).")
    lines += ["", "**Validation checks**", ""]
    lines += [f"- {k}: **{v:.2f}**" for k, v in hl["validation"].items()]
    lines += ["", END]
    return "\n".join(lines)


def main():
    hl = json.loads((config.RESULTS_DIR / "headline.json").read_text())
    readme = ROOT / "README.md"
    txt = readme.read_text()
    if START not in txt:
        print("README has no results markers; nothing to do"); return
    pre, rest = txt.split(START, 1)
    _, post = rest.split(END, 1)
    readme.write_text(pre + block(hl) + post)
    print("README results block updated")


if __name__ == "__main__":
    main()
